using System;
using System.IO;
using System.Linq;
using Newtonsoft.Json.Linq;
using RoomLab.Native;
class Program
{
 static int checks,frames;
 static void Assert(bool ok,string text){checks++;if(!ok)throw new Exception(text);}
 static void Patch(object target,JObject values,bool game=false){if(values==null)return;foreach(var p in values){var name=game?char.ToUpperInvariant(p.Key[0])+p.Key.Substring(1):p.Key;var f=target.GetType().GetField(name);if(f==null)throw new Exception("No patch "+name);f.SetValue(target,p.Value.Type==JTokenType.Null?null:p.Value.ToObject(f.FieldType));}}
 static void Compare(JToken a,JToken b,string path){Assert(a!=null,path+" missing");if(b is JObject ob){if(path.Contains("/objects")||path=="events")Assert(a.Count()==ob.Count,path+" exact property count");foreach(var p in ob)Compare(a[p.Key],p.Value,path+"/"+p.Key);}else if(b is JArray ab){Assert(a is JArray&&a.Count()==ab.Count,path+" count");for(int i=0;i<ab.Count;i++)Compare(a[i],ab[i],path+"/"+i);}else if(b.Type==JTokenType.Integer||b.Type==JTokenType.Float)Assert(Math.Abs(a.Value<double>()-b.Value<double>())<=(path.Contains("Time")||path.Contains("elapsed")||path.Contains("Remaining")?1e-5:.001),path+" got="+a+" expected="+b);else Assert(JToken.DeepEquals(a,b),path+" got="+a+" expected="+b);}
 static void Replay(JObject t){string file=(string)t["name"];string frozenPath="Validation/Native/Traces/"+file+".json";var frozen=File.Exists(frozenPath)?JObject.Parse(File.ReadAllText(frozenPath)):null;var project=NativeProjectLoader.LoadFile("Validation/Native/"+(string)t["project"],new ImportOptions{Profile=ImportProfile.CustomDdl13Preserve});var g=new NativeMotion(project,(string)t["courseId"],(string)t["roomId"]);Patch(g,t["setup"]?["game"] as JObject,true);Patch(g.Player,t["setup"]?["player"] as JObject);
  void Verify(JObject expected,string where){var e=(JObject)expected.DeepClone();if(e["objectStatesRef"]!=null){e["objects"]=t["objectSnapshots"][e["objectStatesRef"].Value<int>()];e.Remove("objectStatesRef");}Compare(g.Snapshot(),e,Path.GetFileName(file)+where);if(frozen!=null){var original=(JObject)(where==" initial"?frozen["initial"]:frozen["frames"][int.Parse(where.Substring(6))]["expected"]).DeepClone();if(original["objectStatesRef"]!=null)original["objects"]=frozen["objectSnapshots"][original["objectStatesRef"].Value<int>()].DeepClone();original.Remove("objectStatesRef");Compare(g.Snapshot(),original,file+" P0"+where);}}
  Verify((JObject)t["initial"]," initial");foreach(JObject f in (JArray)t["frames"]){g.ClearEvents();switch((string)f["op"]){case "tick":g.Tick((double?)f["dt"]??NativeMotion.Step,f["input"]?.ToObject<MotionInput>()??default);break;case "patch":Patch(g,f["game"] as JObject,true);Patch(g.Player,f["player"] as JObject);if(f["ai"] is JObject av){var ac=(JObject)av.DeepClone();if(ac["processing"]!=null){g.AiProcessing=(double)ac["processing"];ac.Remove("processing");}if(ac["cooldown"]!=null){g.AiCooldown=(double)ac["cooldown"];ac.Remove("cooldown");}Patch(g.AI,ac);}break;case "launch":g.Launch((double)f["x"],(double)f["y"]);break;case "startRail":g.StartRail(g.Room.Objects.Find(o=>o.Id==(string)f["id"]));break;case "retry":g.Retry((string)f["reason"]??"重试当前房间");break;case "pause":g.TogglePause();break;case "fire":typeof(NativeMotion).GetMethod("Fire",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(g,new object[]{g.Room.Objects.Find(o=>o.Id==(string)f["id"])});break;case "catch":g.CatchPlayer();break;case "developer":g.SetDeveloperOptions((bool?)f["options"]["enabled"]??false,(bool?)f["options"]["lockHealth"]??false,(bool?)f["options"]["flight"]??false);break;case "temperature":g.SetTemperature((string)f["zone"],(string)f["value"]);break;default:throw new Exception("Unsupported op "+f["op"]);}Verify((JObject)f["expected"]," frame"+f["index"]);Compare(JArray.FromObject(g.Events),f["events"],"events");if(frozen!=null)Compare(JArray.FromObject(g.Events),frozen["frames"][(int)f["index"]]["events"],"P0 events");frames++;}Console.WriteLine("FULL_ORACLE_PASS "+Path.GetFileName(file));}
 static int Main(string[] args){try{foreach(JObject trace in (JArray)JObject.Parse(File.ReadAllText("Validation/Native/P3/immutable-oracle.json"))["traces"])Replay(trace);int smoke=NativeGameplaySmokeChecks.Run(NativeProjectLoader.LoadFile("Validation/Native/Fixtures/ddl13-custom-original.json",new ImportOptions{Profile=ImportProfile.CustomDdl13Preserve}));checks+=smoke;var original=NativeProjectLoader.LoadFile("Validation/Native/Fixtures/ddl13-custom-original.json",new ImportOptions{Profile=ImportProfile.CustomDdl13Preserve});var latest=NativePhysicsDemo.Derive(original);if(args.Contains("--write-demo"))File.WriteAllBytes("Assets/StreamingAssets/RoomLabNative/latest-physics.json",latest.SourceBytes);Console.WriteLine("GAMEPLAY_EDITOR255_SMOKE_PASS checks="+smoke);Console.WriteLine("NATIVE_GAMEPLAY_PASS assertions="+checks+" traces=24 operations="+frames);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
